def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    aisle_matrix = [[0] * (N + 1) for _ in range(M + 1)]

    # Loop through each chatting pair and count the number of positions where an aisle can be added to separate them
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                aisle_matrix[i][j] += 1

    # Loop through each position and count the number of chatting pairs that can be separated by adding an aisle there
    aisle_count = 0
    for i in range(M):
        for j in range(N):
            aisle_count += aisle_matrix[i][j]

    # Select the most effective positions for aisles, aiming to separate as many chatting pairs as possible
    aisle_positions = []
    while aisle_count > 0:
        max_count = 0
        for i in range(M):
            for j in range(N):
                if aisle_matrix[i][j] > max_count:
                    max_count = aisle_matrix[i][j]
                    row = i
                    col = j
        aisle_positions.append((row, col))
        aisle_count -= max_count

    # Return the optimal row and column indices for the aisles
    return " ".join(str(row) for row, _ in aisle_positions), " ".join(str(col) for _, col in aisle_positions)
