def polynomial_to_string(n, coeffs):
    result = ""
    for i in range(len(coeffs)):
        coeff = coeffs[i]
        if coeff != 0:
            if coeff < 0:
                result += "-"
            elif i > 0:
                result += "+"
            abs_coeff = abs(coeff)
            if abs_coeff != 1 or i == 0:
                result += str(abs_coeff)
            if i > 0:
                result += "x"
                if i > 1:
                    result += "^" + str(i)
    return result
```

