def decode(encoded, original, message):
    # Initialize an empty dictionary to store the mapping from encoded letters to original letters
    mapping = {}

    # Loop through each letter in the encoded string
    for i in range(len(encoded)):
        # If the letter is not already in the mapping, add it to the mapping
        if encoded[i] not in mapping:
            mapping[encoded[i]] = original[i]
        # If the letter is already in the mapping and the corresponding original letter is different, return "Failed"
        elif mapping[encoded[i]] != original[i]:
            return "Failed"

    # Initialize an empty string to store the decoded message
    decoded = ""

    # Loop through each letter in the encrypted message
    for letter in message:
        # If the letter is in the mapping, add the corresponding original letter to the decoded message
        if letter in mapping:
            decoded += mapping[letter]
        # If the letter is not in the mapping, return "Failed"
        else:
            return "Failed"

    # Return the decoded message
    return decoded
```

